import Foundation

public enum InterfaceLanguage: String, CaseIterable, Codable {
    case russian = "ru"
    case english = "en"
    case ukrainian = "uk"

    public var title: String {
        switch self {
        case .russian: return "Русский"
        case .english: return "English"
        case .ukrainian: return "Українська"
        }
    }

    public var shortTitle: String { rawValue.uppercased() }
}

/// Small product copy table shared by the app and keyboard extension.
/// Russian strings are stable keys so unknown/older copy safely falls back.
public enum GlassTypeText {
    public static func translate(_ russian: String, to language: InterfaceLanguage) -> String {
        guard language != .russian else { return russian }
        let table = language == .english ? english : ukrainian
        return table[russian] ?? russian
    }

